<script setup lang="ts">
/**
 * The wordmark: `LANtern`, from the artwork in `DESIGN/`.
 *
 * The purple box around "LAN" is a solid shape with the three letters cut out of
 * it, so they show whatever is behind - the header's surface in the app, the
 * banner's background in the README. That is why this needs no background colour
 * of its own, and why one copy serves both themes: the fill is `currentColor`, and
 * the letters stay honest whatever the surface is.
 *
 * `height` is the height in pixels; the width follows the artwork's 272x64, so a
 * caller sets one number and the lockup keeps its proportions.
 */
const props = withDefaults(defineProps<{ height?: number; class?: string }>(), { height: 22 })

/** The artwork is 272 wide and 64 tall; the width is that ratio of the height. */
const width = Math.round((props.height * 272) / 64)
</script>

